namespace Essco.Application.HumanResources;

public sealed record SalaryIncrease(DateOnly Date, decimal Percentage, decimal PreviousSalary, decimal NewSalary, decimal Amount, string Reason, string CreatedBy);
public sealed record SalaryIncreaseInput(string EmployeeId, DateOnly Date, decimal Percentage, string Reason, string CreatedBy);
public sealed record EmployeeAdditional(string Type, decimal Amount, DateOnly CreatedAt, bool Annulled);
public interface IEmployeeCompensationRepository { ValueTask<IReadOnlyCollection<SalaryIncrease>> IncreasesAsync(string id, CancellationToken t); ValueTask<IReadOnlyCollection<EmployeeAdditional>> AdditionalsAsync(string id, CancellationToken t); ValueTask<bool> AddIncreaseAsync(SalaryIncreaseInput x, CancellationToken t); ValueTask<bool> AddAdditionalAsync(string id, string type, decimal amount, CancellationToken t); ValueTask<bool> AnnulAdditionalsAsync(string id, CancellationToken t); }
public sealed class EmployeeCompensationService(IEmployeeCompensationRepository repository)
{ public static readonly string[] AdditionalTypes = ["Viaticos", "Combustibles"]; public ValueTask<IReadOnlyCollection<SalaryIncrease>> IncreasesAsync(string id, CancellationToken t) => repository.IncreasesAsync(id, t); public ValueTask<IReadOnlyCollection<EmployeeAdditional>> AdditionalsAsync(string id, CancellationToken t) => repository.AdditionalsAsync(id, t); public async ValueTask<bool> AddIncreaseAsync(SalaryIncreaseInput x, CancellationToken t) => !string.IsNullOrWhiteSpace(x.EmployeeId) && x.Date != default && x.Percentage > 0 && x.Percentage <= 100 && !string.IsNullOrWhiteSpace(x.Reason) && await repository.AddIncreaseAsync(x with { Reason = x.Reason.Trim(), CreatedBy = x.CreatedBy.Trim() }, t); public async ValueTask<bool> AddAdditionalAsync(string id, string type, decimal amount, CancellationToken t) => AdditionalTypes.Contains(type, StringComparer.OrdinalIgnoreCase) && amount > 0 && await repository.AddAdditionalAsync(id, type, amount, t); public ValueTask<bool> AnnulAdditionalsAsync(string id, CancellationToken t) => repository.AnnulAdditionalsAsync(id, t); }
